# owner: platform
"""Seat students in rows, ordered by last name."""

from typing import List

from rosterkit.models import Student

Roster = List[Student]

def check_inputs(students: Roster, seats: int) -> None:
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def name_key(student: Student) -> tuple:
    last = student.last_name.lower()
    return (last, student.first_name.lower())

def split_rows(ordered: Roster, seats: int) -> List[Roster]:
    stops = range(0, len(ordered), seats)
    return [ordered[at:at + seats] for at in stops]

def format_row(number: int, chunk: Roster) -> str:
    names = " | ".join(item.display_name for item in chunk)
    return f"Row {number}: {names}"

# ---
def seating_rows(students: Roster, seats: int) -> List[str]:
    check_inputs(students, seats)
    ordered = sorted(students, key=name_key)
    chunks = split_rows(ordered, seats)
    return [
        format_row(index, chunk)
        for index, chunk in enumerate(chunks, 1)
    ]
